///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name keyEvent
 * @description key Event 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.keyEvent = async function (e) {
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) === 13 || (typeof e !== 'undefined' && e === 13)) {
        if ($c.util.getKeyCode(event) === 13) {
            if (fnAKCKwdSearchCodeType(($c.util.getComponent('ipt_kwd')))) {
                let varkwd = $c.util.getComponent('ipt_kwd').getValue(); if (varkwd == null) { varkwd = ''; }
                if (varkwd.length >= 1) {
                    await scwin.fnSearchCorpName();
                }
            }
        }
    }
};

/**
 * @method
 * @name fnInit
 * @description fn Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnInit = async function () {
    // 수동 전환 필요: fnDisplaySearchBtnDates(N) / fnDisplaySearchBtnDatesOnlyPeriod(N) → 작업본 dateSetting 관례로 재설계 (조회 기간 프리셋)
    //   KRX 방향: 재설계 축 — 작업본 정답지 관례 = scwin.dateSetting() + 기간 버튼 핸들러(btn_3mon_onclick 등)가 캘린더 setValue 로 기간을 직접 세움(ULDINF05800 계열 실증). 1:1 대체 함수가 없고 속성 승격도 아님 — 조회 영역 저작 관례로 실현. 요청 명부에서 제외(재설계 분류).
    //   근거: catalog/function-map (이 주석은 고쳐 쓴 뒤 지우십시오)
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDates( "3 ') */
    let varkwd = $c.util.getComponent('ipt_kwd').getValue(); if (varkwd == null) { varkwd = ''; }
    if (varkwd.length >= 1) {
        await scwin.fnSearchCorpName();
    }
};

/**
 * @method
 * @name fnSearchCorpName
 * @description fn Search Corp Name 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpName = async function () {
    let varkwd = $c.util.getComponent('ipt_kwd').getValue(); if (varkwd == null) { varkwd = ''; }
    if (varkwd.length < 1) {
        await $c.win.alert("검색어를 입력해 주세요.");
        return;
    }
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("repIsuSrtCd", "");
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("isurCd", "");
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("pageIndex", "1");
    if (varkwd !== "") {
        $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("searchCorpName", varkwd);
        /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnAKCKwdSearchCorpName( " ') */
    } else {
        await scwin.fnSearch();
    }
};

/**
 * @method
 * @name fnSearchCorpNameAllCallBack
 * @description fn Search Corp Name All Call Back 처리
 * @param {*} items items
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpNameAllCallBack = async function (items) {
    if (items.length === 1) {
        await scwin.fnSearchCorpCode(items[0]);
        fnSetCookieCrop(items);
    } else {
        if (items.length > 1) {
            await scwin.fnSearch();
        } else {
            await scwin.fnSearchCorpCode(null);
        }
    }
};

/**
 * @method
 * @name fnSearchCorpCode
 * @description fn Search Corp Code 처리
 * @param {*} item item
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpCode = async function (item) {
    if (item == null) {
        $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("repIsuSrtCd", '');
        $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("isurCd", '');
    } else {
        $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("repIsuSrtCd", item.repisusrtcd);
        $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("isurCd", item.isurcd);
        $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("repIsuCd", item.repisucd);
    }
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    if (!$c.date.isDate($c.util.getComponent('cal_fromData').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toData').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (($c.util.getComponent('cal_fromData').getValue() == null ? '' : String($c.util.getComponent('cal_fromData').getValue())) !== '' && ($c.util.getComponent('cal_toData').getValue() == null ? '' : String($c.util.getComponent('cal_toData').getValue())) !== '') {
        if (!($c.date.diffDate($c.util.getComponent('cal_fromData').getValue(), $c.util.getComponent('cal_toData').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
            return;
        }
    }
    const valSrchFd = $("#searchForm").find("select[name=srchFd]").val();
    if (valSrchFd === "0") {
        $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("forward", "searchtotalinfo_sub");
        $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("method", "searchTotalInfoSub");
        $("#mainContents").empty();
        (($c.util.getComponent('TotalLayer')) && ($c.util.getComponent('TotalLayer')).removeAll ? ($c.util.getComponent('TotalLayer')).removeAll() : (($c.util.getComponent('TotalLayer')) && ($c.util.getComponent('TotalLayer')).setValue ? ($c.util.getComponent('TotalLayer')).setValue('') : void 0));
        scwin.TotalLayer.setStyle("display", "none");
        await scwin.tx_fnSearch_ajaxsubmit();
    } else {
        if (valSrchFd === "1") {
            $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("forward", "searchtotalinfo_total");
            $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("method", "searchTotalInfoSub");
            $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("fdName", "all_disclosure_idx");
            $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("scn", "disclosure");
            $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("currentPageSize", "15");
            $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("pageIndex", "1");
            $("#mainContents").empty();
            (($c.util.getComponent('TotalLayer')) && ($c.util.getComponent('TotalLayer')).removeAll ? ($c.util.getComponent('TotalLayer')).removeAll() : (($c.util.getComponent('TotalLayer')) && ($c.util.getComponent('TotalLayer')).setValue ? ($c.util.getComponent('TotalLayer')).setValue('') : void 0));
            scwin.TotalLayer.setStyle("display", "");
            await scwin.tx_fnSearch_ajaxsubmit_1();
        } else {
            if (valSrchFd === "2") {
                $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("forward", "searchtotalinfo_detail");
                $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("method", "searchTotalInfoSub");
                $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("fdName", "all_mktact_idx");
                $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("scn", "mktact");
                $("#mainContents").empty();
                (($c.util.getComponent('TotalLayer')) && ($c.util.getComponent('TotalLayer')).removeAll ? ($c.util.getComponent('TotalLayer')).removeAll() : (($c.util.getComponent('TotalLayer')) && ($c.util.getComponent('TotalLayer')).setValue ? ($c.util.getComponent('TotalLayer')).setValue('') : void 0));
                scwin.TotalLayer.setStyle("display", "none");
                await scwin.tx_fnSearch_ajaxsubmit_2();
            } else {
                if (valSrchFd === "3") {
                    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("forward", "searchtotalinfo_detail");
                    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("method", "searchTotalInfoSub");
                    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("fdName", "all_news_idx");
                    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("scn", "news");
                    $("#mainContents").empty();
                    (($c.util.getComponent('TotalLayer')) && ($c.util.getComponent('TotalLayer')).removeAll ? ($c.util.getComponent('TotalLayer')).removeAll() : (($c.util.getComponent('TotalLayer')) && ($c.util.getComponent('TotalLayer')).setValue ? ($c.util.getComponent('TotalLayer')).setValue('') : void 0));
                    scwin.TotalLayer.setStyle("display", "none");
                    await scwin.tx_fnSearch_ajaxsubmit_3();
                }
            }
        }
    }
};

/**
 * @method
 * @name fnTotalSearchCallBack
 * @description fn Total Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnTotalSearchCallBack = function (data) {
    (($c.util.getComponent('TotalLayer')) && ($c.util.getComponent('TotalLayer')).removeAll ? ($c.util.getComponent('TotalLayer')).removeAll() : (($c.util.getComponent('TotalLayer')) && ($c.util.getComponent('TotalLayer')).setValue ? ($c.util.getComponent('TotalLayer')).setValue('') : void 0)).append(data);
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    if (data === "") {
        $("#mainContents").load("/error.jsp");
    } else {
        $("#mainContents").empty().append(data);
    }
};

